'use client';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import dynamic from 'next/dynamic';
import Link from 'next/link';
import { motion, AnimatePresence, useReducedMotion } from 'framer-motion';
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, BrainCircuit, CalendarDays, Camera, Check, ChevronDown, ClipboardCheck, Download, FileText, Filter, Github, Globe2, GraduationCap, Leaf, LayoutDashboard, LogOut, Menu, Plus, Recycle, Search, Eye, Settings2, ShieldCheck, Sparkles, Sun, Moon, Target, Trash2, Trophy, Upload, X, Pencil, ClipboardList, AlertTriangle, BookOpen, Lock, HelpCircle } from 'lucide-react';
