import type { Analytics, Audit, Evidence, Lookup, View, Workspace } from '@/lib/types';
const CampusScene=dynamic(()=>import('@/components/three/CampusScene'),{ssr:false,loading:()=> <Skeleton height={480}/>});
const WasteScene=dynamic(()=>import('@/components/three/WasteScene'),{ssr:false,loading:()=> <Skeleton height={370}/>});
const NAV:{key:View;label:string;icon:typeof Activity}[]=[{key:'overview',label:'Overview',icon:LayoutDashboard},{key:'twin',label:'Campus Digital Twin',icon:Globe2},{key:'audits',label:'Plastic Audit',icon:ClipboardCheck},{key:'analytics',label:'Analytics',icon:BarChart3},{key:'intelligence',label:'AI Intelligence',icon:BrainCircuit},{key:'categories',label:'Waste Categories',icon:Recycle},{key:'recycling',label:'Recycling Tracker',icon:Leaf},{key:'goals',label:'Sustainability Goals',icon:Target},{key:'reports',label:'Impact Reports',icon:FileText},{key:'evidence',label:'Evidence Gallery',icon:Camera},{key:'leaderboard',label:'Leaderboard',icon:Trophy},{key:'settings',label:'Settings',icon:Settings2}];
const nf=(n:number|null|undefined,dec=2)=>n===null||n===undefined?'—':n.toLocaleString('en-IN',{maximumFractionDigits:dec,minimumFractionDigits:dec});
type Mode='demo'|'real';type Me={id:string;email:string;role:string;campus:{id:string;name:string}|null};
function KpiCard({icon:Icon,label,value,unit,detail,trend}:{icon:typeof Activity;label:string;value:string;unit?:string;detail:string;trend?:number|null}){return <motion.div whileHover={{y:-3}} transition={{type:'spring',stiffness:250}} className="kpi-card"><div className="kpi-top"><span className="kpi-icon"><Icon size={21}/></span><ArrowUpRight size={16} className="kpi-decoration"/></div><div className="kpi-label">{label}</div><div className="kpi-value">{value}<span>{unit}</span></div><div className="kpi-detail">{trend!==undefined&&trend!==null&&<span className={`kpi-delta ${trend>=0?'positive':'negative'}`}>{trend>=0?'↓':'↑'} {nf(Math.abs(trend))}% </span>}{detail}</div></motion.div>}
function DataBanner({mode}:{mode:Mode}){return <div className={`mode-banner ${mode==='demo'?'demo-banner':'real-banner'}`} role="status"><span className="mode-banner-pulse"/>{mode==='demo'?<><strong>DEMO DATA — NOT ACTUAL ENVIRONMENTAL MEASUREMENTS</strong><span>Simulated campus observations for interface exploration. Demo actions do not affect real records.</span></>:<><strong>REAL AUDIT MODE</strong><span>Showing only authenticated campus records. No demo measurements are included.</span></>}</div>}
function Onboarding({onCreated}:{onCreated:()=>Promise<void>}){const[name,setName]=useState(''),[error,setError]=useState(''),[loading,setLoading]=useState(false);async function create(){setLoading(true);setError('');try{await api('/api/campuses',{method:'POST',body:JSON.stringify({name})});await onCreated()}catch(e){setError(e instanceof Error?e.message:'Could not create campus')}finally{setLoading(false)}}return <div className="setup-panel glass-panel"><span className="setup-symbol"><GraduationCap size={37}/></span><span className="eyebrow"><span className="eyebrow-dot"/> YOUR OWN SUSTAINABILITY WORKSPACE</span><h2>Set up your campus.</h2><p>Build an independent real-data workspace. Add departments and zones in Settings before recording your first measured audit.</p><label>Campus name<input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Green Valley University" minLength={2} maxLength={160}/></label>{error&&<div className="form-error">{error}</div>}<Button disabled={loading||name.trim().length<2} onClick={create}>{loading?'Creating…':'Create campus workspace'} <ArrowRight size={16}/></Button><small>Creating this campus makes you its administrator. This demo uses one workspace per account.</small></div>}
function AuthPanel({onAuthenticated}:{onAuthenticated:()=>Promise<void>}){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[status,setStatus]=useState(''),[busy,setBusy]=useState(false),[signup,setSignup]=useState(false);async function submit(){const sup=supabase();if(!sup)return;setStatus('');setBusy(true);try{const {data,error}=signup?await sup.auth.signUp({email,password}):await sup.auth.signInWithPassword({email,password});if(error)throw error;if(signup&&!data.session){setStatus('Account created. Check your email for a confirmation link before signing in.')}else await onAuthenticated()}catch(e){setStatus(e instanceof Error?e.message:'Authentication failed')}finally{setBusy(false)}}return <div className="setup-panel glass-panel"><span className="setup-symbol"><Lock size={31}/></span><span className="eyebrow"><span className="eyebrow-dot"/> SUPABASE AUTH</span><h2>{signup?'Create your account':'Sign in to real audits'}</h2><p>Authentic measurements are isolated from the public demonstration. Sign in to access your campus data securely.</p>{supabaseConfigured?<form onSubmit={e=>{e.preventDefault();void submit()}}><label>Email address<input type="email" autoComplete="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="your@email.com"/></label><label>Password<input type="password" autoComplete={signup?'new-password':'current-password'} minLength={6} required value={password} onChange={e=>setPassword(e.target.value)}/></label><Button disabled={busy} type="submit">{busy?'Processing…':signup?'Create account':'Sign in'} <ArrowRight size={16}/></Button><button type="button" className="subtle-link" onClick={()=>setSignup(!signup)}>{signup?'Already registered? Sign in':'Need an account? Sign up'}</button></form>:<div className="form-error">Supabase Auth is not configured. Add your project URL and publishable key to frontend/.env.local, or enable development authentication locally.</div>}{status&&<div role="status" className="form-note">{status}</div>}</div>}

export default function DashboardApp(){
 const [mode,setMode]=useState<Mode>('demo'),[view,setView]=useState<View>('overview'),[mobileNav,setMobileNav]=useState(false),[light,setLight]=useState(false);
 const [dates,setDates]=useState(initialDates),[search,setSearch]=useState(''),[me,setMe]=useState<Me|null>(null),[workspace,setWorkspace]=useState<Workspace|null>(null);
 const [rows,setRows]=useState<Audit[]>([]),[stats,setStats]=useState<Analytics|null>(null),[evidence,setEvidence]=useState<Evidence[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[authNeeded,setAuthNeeded]=useState(false),[formOpen,setFormOpen]=useState(false),[editing,setEditing]=useState<Audit|null>(null),[notice,setNotice]=useState('');
 const reduced=useReducedMotion();
 useEffect(()=>{const query=new URLSearchParams(window.location.search).get('view');if(NAV.some(v=>v.key===query))setView(query as View)},[]);
 const navigate=(v:View)=>{setView(v);setMobileNav(false);window.history.replaceState(null,'',`${window.location.pathname}?view=${v}`)};
 const loadReal=useCallback(async()=>{setBusy(true);setError('');setAuthNeeded(false);try{
  const current=await api<Me>('/api/me');setMe(current);
  if(!current.campus){setWorkspace(null);setRows([]);setStats(null);setEvidence([]);return}
  const [ws,a,ins,ev]=await Promise.all([api<Workspace>('/api/workspace'),api<Audit[]>('/api/audits'),api<Analytics>(`/api/analytics?start=${dates.start}&end=${dates.end}`),api<Evidence[]>('/api/evidence')]);
  setWorkspace(ws);setRows(a);setStats(ins);setEvidence(ev);
 }catch(e){const msg=e instanceof Error?e.message:'Real data could not be loaded';setError(msg);if(msg.toLowerCase().includes('sign in')||msg.toLowerCase().includes('auth')||msg.includes('401'))setAuthNeeded(true)}finally{setBusy(false)}},[dates.start,dates.end]);
 useEffect(()=>{if(mode==='real')void loadReal()},[mode,loadReal]);
 async function changeMode(m:Mode){setMode(m);setNotice('');if(m==='demo'){setError('');setAuthNeeded(false)}}
 const demoStats=useMemo(()=>computeDemo(demoAudits,dates.start,dates.end),[dates]);
 const data=mode==='demo'?demoStats:stats;
 const allRows=mode==='demo'?demoAudits:rows;
 const filteredRows=(data?.rows||[]).filter(r=>`${r.submission_id} ${r.department} ${r.zone} ${r.category} ${r.item_type} ${r.auditor_name}`.toLowerCase().includes(search.toLowerCase()));
 const ws=mode==='demo'?demoWorkspace:workspace;
 const realReady=mode==='real'&&!!me?.campus&&!!workspace;
 const editable=realReady&&(me?.role==='admin'||me?.role==='auditor');
 const m=data?.metrics;
 async function signOut(){const s=supabase();await s?.auth.signOut();setMe(null);setWorkspace(null);setStats(null);setRows([]);setAuthNeeded(true)}
 async function deleteAudit(a:Audit){if(!window.confirm(`Archive audit ${a.submission_id}? The activity log will be preserved.`))return;try{await api(`/api/audits/${a.id}`,{method:'DELETE'});await loadReal();setNotice('Audit archived. Activity log preserved.')}catch(e){setNotice(e instanceof Error?e.message:'Unable to archive audit')}}
 function newAudit(a:Audit|null=null){setEditing(a);setFormOpen(true)}
 const params=`start=${dates.start}&end=${dates.end}`;
 async function doExport(type:'pdf'|'csv'){if(mode==='demo'){setNotice('Demo data cannot be exported as a real environmental report. Switch to Real Audit Mode.');return}try{await downloadReport(`/api/reports/${type}?${params}`,`EcoSphere-Report-${dates.start}-${dates.end}.${type}`);setNotice(`${type.toUpperCase()} report generated from real measured records.`)}catch(e){setNotice(e instanceof Error?e.message:'Report failed')}}
 return <div className={`app-shell ${light?'theme-light':''}`}><aside className={`sidebar ${mobileNav?'sidebar-open':''}`}><div className="sidebar-top"><Logo dashboard/><button className="mobile-menu dashboard-close" aria-label="Close navigation" onClick={()=>setMobileNav(false)}><X size={20}/></button></div><div className="sidebar-workspace"><span className="workspace-avatar"><GraduationCap size={19}/></span><div><small>ACTIVE WORKSPACE</small><strong>{mode==='demo'?'Evergreen Campus':me?.campus?.name||'Your campus'}</strong></div><ChevronDown size={15}/></div><div className="sidebar-label">WORKSPACE</div><nav className="dashboard-nav" aria-label="Dashboard sections">{NAV.map(({key,label,icon:Icon},index)=><button type="button" key={key} onClick={()=>navigate(key)} className={`nav-item ${view===key?'active':''}`}><Icon size={18}/><span>{label}</span>{key==='intelligence'&&<span className="nav-beta">RULES</span>}</button>)}</nav><div className="sidebar-bottom"><div className="sidebar-sdg"><span className="sdg-number">12</span><div><b>RESPONSIBLE</b><small>CONSUMPTION &amp; PRODUCTION</small></div><Leaf size={20}/></div><p>Crafted by Raja ✨</p><Link href="/" className="sidebar-back">← Back to website</Link></div></aside>
 <div className="main-column"><header className="dashboard-header"><div className="dashboard-head-left"><button className="mobile-menu dash-hamburger" aria-label="Open navigation" onClick={()=>setMobileNav(true)}><Menu/></button><div className="breadcrumb">WORKSPACE <span>/</span> <b>{NAV.find(n=>n.key===view)?.label}</b></div></div><div className="header-tools"><div className="searchbar"><Search size={16}/><input aria-label="Search audit records" placeholder="Search audits, zones..." value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')navigate('audits')}}/><kbd>⌘ K</kbd></div><button aria-label="Toggle dashboard theme" title="Toggle dashboard theme" className="tool-button" onClick={()=>setLight(!light)}>{light?<Moon size={18}/>:<Sun size={18}/>}</button><button aria-label="Notifications (none configured)" title="Notifications not configured" className="tool-button"><Bell size={18}/><i/></button><div className="profile-pill" title={mode==='demo'?'Demo visitor':me?.email||'Not signed in'}><span>{mode==='demo'?'D':(me?.email||'R').slice(0,1).toUpperCase()}</span><div><strong>{mode==='demo'?'Demo Visitor':me?.role||'Guest'}</strong><small>{mode==='demo'?'Exploration Mode':me?.email||'Real Audit Mode'}</small></div></div></div></header>
 <div className="dashboard-content"><div className="dashboard-heading"><div><div className="dashboard-eyebrow"><span/> ECOSPHERE INTELLIGENCE PLATFORM <span className="dashboard-version">V 1.0</span></div><h1>{view==='overview'?'Good to see you.':NAV.find(n=>n.key===view)?.label}<span className="title-sparkle"> ✦</span></h1><p>{view==='overview'?"Let's make sustainability measurable, one observation at a time.":view==='twin'?'Explore plastic waste spatially across your campus.':view==='audits'?'Capture and manage authentic plastic waste measurements.':'Evidence-first environmental intelligence for your campus.'}</p></div><div className="heading-actions"><div className="mode-switch" role="group" aria-label="Data mode"><button className={mode==='demo'?'on':''} onClick={()=>void changeMode('demo')}>◇ Demo</button><button className={mode==='real'?'on':''} onClick={()=>void changeMode('real')}>● Real Data</button></div>{editable&&<Button size="small" onClick={()=>newAudit()}><Plus size={16}/> New Audit</Button>}</div></div>
 <DataBanner mode={mode}/><div className="dashboard-controls"><div className="period-legend"><CalendarDays size={16}/> REPORTING WINDOW <span>·</span> {data?.period.start||dates.start} — {data?.period.end||dates.end}</div><div className="date-controls"><label>From <input aria-label="Start date" type="date" value={dates.start} max={dates.end} onChange={e=>setDates(d=>({...d,start:e.target.value}))}/></label><span>→</span><label>To <input aria-label="End date" type="date" value={dates.end} min={dates.start} max={initialDates().end} onChange={e=>setDates(d=>({...d,end:e.target.value}))}/></label></div></div>
 {notice&&<div className="toast" role="status">{notice}<button aria-label="Dismiss" onClick={()=>setNotice('')}><X size={15}/></button></div>}
 {mode==='real'&&!busy&&!data&&<>{authNeeded||(!me&&!devMode)?<AuthPanel onAuthenticated={loadReal}/>:error?<div className="setup-panel glass-panel"><AlertTriangle size={29}/><h2>Real workspace unavailable</h2><p>{error}</p><Button onClick={()=>void loadReal()}>Retry connection <ArrowRight size={16}/></Button><p className="tiny-note">Start the FastAPI server and configure authentication before connecting real audits.</p></div>:!me?.campus?<Onboarding onCreated={loadReal}/>:null}</>}
 {mode==='real'&&busy&&!data&&<div className="dashboard-grid"><Skeleton height={140}/><Skeleton height={140}/><Skeleton height={140}/><Skeleton height={140}/></div>}
 {data&&ws&&<AnimatePresence mode="wait"><motion.div key={view} initial={reduced?false:{opacity:0,y:9}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-7}} transition={{duration:.2}}>
 {view==='overview'&&<><div className="kpi-grid"><KpiCard icon={Recycle} label="Total Plastic Recorded" value={nf(m?.total_kg)} unit="kg" detail="Sum of measured weights"/><KpiCard icon={Leaf} label="Single-Use Plastic" value={nf(m?.single_use_kg)} unit="kg" detail={`${nf(m?.single_use_pct)}% of measured total`}/><KpiCard icon={ArrowDownRight} label={m?.reduction_kg!==null&&(m?.reduction_kg||0)<0?'Waste Increase':'Plastic Waste Reduced'} value={nf(m?.reduction_kg===null?null:Math.abs(m?.reduction_kg||0))} unit="kg" detail="Against prior equal-length period" trend={m?.reduction_pct}/><KpiCard icon={Recycle} label="Recycling Rate" value={nf(m?.recycling_rate)} unit="%" detail="Confirmed recycled / measured"/><KpiCard icon={ClipboardCheck} label="Completed Audits" value={String(m?.audits??0)} detail="Records in selected period"/><KpiCard icon={Target} label="Sustainability Index" value={nf(m?.sustainability_score,1)} unit="/100" detail="Provisional, not certified"/></div><div className="charts-grid"><TrendChart data={data.by_day}/><CategoryChart data={data.by_category}/><ZoneChart data={data.by_zone}/><RecyclingChart rows={data.rows}/></div><div className="overview-footer"><div className="method-note"><ShieldCheck size={21}/><div><strong>Evidence-first by design</strong><p>Reduction requires comparable periods; recycling counts only confirmed weight. Results are measurements from audits, not live sensors.</p></div></div><button className="text-link" onClick={()=>navigate('analytics')}>Detailed analytics <ArrowUpRight size={17}/></button></div></>}
 {view==='audits'&&<AuditTable rows={filteredRows} mode={mode} editable={editable} onEdit={newAudit} onDelete={deleteAudit} onNew={()=>newAudit()} onExport={()=>void doExport('csv')} onImportDone={loadReal} search={search} setSearch={setSearch}/>}
 {view==='analytics'&&<><div className="analytics-summary"><div><strong>{nf(m?.total_kg)} kg</strong><span>MEASURED TOTAL</span></div><div><strong>{nf(data.baseline.available?data.baseline.total_kg:null)} kg</strong><span>PRIOR MATCHED PERIOD</span></div><div><strong>{nf(m?.reduction_pct)}%</strong><span>CHANGE VS BASELINE (+ = REDUCTION)</span></div></div><div className="charts-grid"><TrendChart data={data.by_day}/><ReductionAreaChart data={data.reduction_trend}/><PerformanceRadar data={data}/><CompositionTreemap data={data.by_category}/><ZoneChart data={data.by_zone}/><RecyclingChart rows={data.rows}/><AuditCalendar rows={data.rows}/></div><WasteVisualization data={data.by_category} reduced={!!reduced}/><div className="glass-panel notes-card"><h3>Calculation transparency</h3><p>Baseline: <b>{data.baseline.start} — {data.baseline.end}</b> (same number of days). Waste reduction = baseline measured kg − current measured kg. A negative result means waste increased. This comparison does not correct for differences in audit intensity. The EcoSphere index is provisional, not a formal SDG certification.</p><div className="weight-pills">{Object.entries(data.score_weights).map(([k,v])=><span key={k}>{k.replaceAll('_',' ')} <b>{v}%</b></span>)}</div></div></>}
 {view==='twin'&&<TwinSection mode={mode} ws={ws} data={data} reduced={!!reduced} onAdd={()=>navigate('settings')}/>}
 {view==='intelligence'&&<IntelligenceSection mode={mode} data={data} dates={dates}/>}
 {view==='categories'&&<><div className="two-col"><CategoryChart data={data.by_category}/><CompositionTreemap data={data.by_category}/></div><div className="records-section"><h3>Waste category breakdown</h3><div className="category-list">{data.by_category.length?data.by_category.map((c,i)=><div key={c.name}><span className="list-number">{String(i+1).padStart(2,'0')}</span><b>{c.name}</b><div className="category-bar"><i style={{width:`${Math.max(2,c.value/(data.by_category[0]?.value||1)*100)}%`}}/></div><strong>{nf(c.value)} kg</strong></div>):<EmptyState title="No categories measured" description="Submit an audit to see the breakdown."/>}</div></div></>}
 {view==='recycling'&&<RecyclingSection mode={mode} data={data} role={me?.role} onUpdated={loadReal}/>}
 {view==='goals'&&<GoalsSection mode={mode} data={data} onUpdate={loadReal} ws={ws}/>}
 {view==='reports'&&<ReportsSection mode={mode} data={data} dates={dates} onExport={doExport}/>}
 {view==='evidence'&&<EvidenceSection mode={mode} items={evidence} role={me?.role} onUpdate={loadReal}/>}
 {view==='leaderboard'&&<LeaderboardSection data={data} rows={allRows} dates={dates}/>}
 {view==='settings'&&<SettingsSection mode={mode} me={me} workspace={ws} onRefresh={loadReal} onLogout={signOut}/>}
 </motion.div></AnimatePresence>}
 <div className="dash-footer"><span><Leaf size={13}/> EcoSphere AI · Intelligence for a Plastic-Free Tomorrow.</span><span>Crafted by <b>Raja</b> ✨ <span>· © 2026</span></span></div>
 </div></div>{mobileNav&&<button className="mobile-overlay" aria-label="Close sidebar" onClick={()=>setMobileNav(false)}/>}<AuditForm open={formOpen} onOpenChange={setFormOpen} editing={editing} workspace={ws||demoWorkspace} onSaved={loadReal}/></div>
}

function AuditTable({rows,mode,editable,onEdit,onDelete,onNew,onExport,onImportDone,search,setSearch}:{rows:Audit[];mode:Mode;editable:boolean;onEdit:(a:Audit)=>void;onDelete:(a:Audit)=>void;onNew:()=>void;onExport:()=>void;onImportDone:()=>Promise<void>;search:string;setSearch:(x:string)=>void}){
 const [importError,setImportError]=useState(''),[importing,setImporting]=useState(false),[selected,setSelected]=useState<Audit|null>(null),[history,setHistory]=useState<{action:string;created_at:string}[]>([]);const fileRef=useRef<HTMLInputElement>(null);
 async function inspect(a:Audit){setSelected(a);if(mode==='real')try{const res=await api<{action:string;created_at:string}[]>(`/api/audits/${a.id}/history`);setHistory(res)}catch{setHistory([])}else setHistory([])}
 async function importCSV(file:File){setImporting(true);setImportError('');try{const fd=new FormData();fd.append('file',file);const result=await api<{imported:number}>('/api/audits/import',{method:'POST',body:fd});setImportError(`Imported ${result.imported} validated measured audit records.`);await onImportDone()}catch(e){setImportError(e instanceof Error?e.message:'CSV import failed')}finally{setImporting(false)}}
 return <div className="records-section"><div className="records-heading"><div><h3>Plastic Audit Registry</h3><p>{rows.length} observations matching the active reporting window</p></div><div className="records-actions">{mode==='real'&&<><input aria-label="Import CSV" hidden type="file" accept=".csv,text/csv" ref={fileRef} onChange={e=>{const f=e.target.files?.[0];if(f)void importCSV(f);e.target.value=''}}/><Button size="small" variant="outline" disabled={!editable||importing} onClick={()=>fileRef.current?.click()}><Upload size={15}/> {importing?'Importing…':'Import CSV'}</Button><Button size="small" variant="outline" onClick={onExport}><Download size={15}/> Export CSV</Button></>}{editable&&<Button size="small" onClick={onNew}><Plus size={15}/> New Audit</Button>}</div></div>{importError&&<div role="status" className="form-note">{importError}</div>}<div className="table-scroll"><table className="audit-table"><thead><tr><th>AUDIT ID</th><th>DATE</th><th>ZONE / DEPARTMENT</th><th>WASTE CATEGORY</th><th>WEIGHT</th><th>TYPE</th><th>RECYCLING</th><th>ACTIONS</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><strong>{r.submission_id}</strong><small>{r.auditor_name}</small></td><td>{r.audit_date}</td><td><strong>{r.zone}</strong><small>{r.department}</small></td><td>{r.category}<small>{r.item_type}</small></td><td><b>{nf(r.weight_kg)} kg</b></td><td><Badge tone={r.single_use?'amber':'mint'}>{r.single_use?'Single-use':'Reusable'}</Badge></td><td><Badge tone={r.confirmed_recycled_kg>0?'mint':'muted'}>{r.confirmed_recycled_kg>0?'Confirmed':'Not confirmed'}</Badge></td><td><div className="table-actions"><button aria-label={`View ${r.submission_id}`} title="View audit and history" onClick={()=>void inspect(r)}><Eye size={15}/></button>{editable?<><button aria-label={`Edit ${r.submission_id}`} title="Edit audit" onClick={()=>onEdit(r)}><Pencil size={15}/></button><button aria-label={`Delete ${r.submission_id}`} title="Archive audit" onClick={()=>onDelete(r)}><Trash2 size={15}/></button></>:null}</div></td></tr>)}</tbody></table>{!rows.length&&<EmptyState title="No audits in this period" description={mode==='demo'?'Try expanding the date range or adjusting the search.':'Start a real audit with a measured weight and the correct zone.'} action={editable?<Button size="small" onClick={onNew}><Plus size={15}/> New audit</Button>:undefined}/>}</div><div className="table-footer">All weights in kilograms · Original records are retained in the database with audit modification history.{mode==='demo'&&<b> · SIMULATED ROWS</b>}</div><AuditDetails selected={selected} onClose={()=>setSelected(null)} history={history} mode={mode}/></div>
}
function AuditDetails({selected,onClose,history,mode}:{selected:Audit|null;onClose:()=>void;history:{action:string;created_at:string}[];mode:Mode}){return <>{selected&&<div className="detail-overlay" role="presentation" onClick={onClose}><section className="detail-drawer" role="dialog" aria-modal="true" aria-label="Audit details" onClick={e=>e.stopPropagation()}><div className="detail-top"><span className="eyebrow"><span className="eyebrow-dot"/> AUDIT PROFILE</span><button aria-label="Close details" className="icon-button" onClick={onClose}><X size={17}/></button></div><h2>{selected.submission_id}</h2><p>{selected.audit_date} · {selected.auditor_name}</p>{mode==='demo'&&<Badge tone="amber">SIMULATED — NOT A REAL MEASUREMENT</Badge>}<div className="detail-fields">{[['Campus zone',selected.zone],['Department',selected.department],['Category',selected.category],['Item type',selected.item_type],['Item count',selected.item_count],['Measured weight',`${nf(selected.weight_kg)} kg`],['Classification',selected.single_use?'Single-use':'Reusable'],['Recyclable material',selected.recyclable?'Yes':'No'],['Disposal',selected.disposal_method],['Confirmed recycling',`${nf(selected.confirmed_recycled_kg)} kg`],['Observations',selected.observations||'None recorded'],['Corrective action',selected.corrective_action||'None recorded']].map(([k,v])=><div key={String(k)}><span>{k}</span><b>{v}</b></div>)}</div><h3>Modification history</h3>{mode==='demo'?<p className="muted-text">Demonstration records are not stored in an activity log.</p>:history.length?history.map((h,i)=><div className="detail-history" key={i}><Badge>{h.action}</Badge><span>{new Date(h.created_at).toLocaleString()}</span></div>):<p className="muted-text">History not available.</p>}</section></div>}</>}
function WasteVisualization({data,reduced}:{data:{name:string;value:number}[];reduced:boolean}){const [canRender,setCanRender]=useState(false);useEffect(()=>{try{const canvas=document.createElement('canvas');setCanRender(Boolean(canvas.getContext('webgl2')||canvas.getContext('webgl')))}catch{setCanRender(false)}},[]);return <div className="glass-panel waste-panel"><div className="waste-panel-heading"><div><span className="eyebrow"><span className="eyebrow-dot"/> 3D MATERIAL INTELLIGENCE</span><h3>Waste Mass Explorer</h3><p>Interactive spatial illustration based on the measured category weights, not literal item counts.</p></div><Badge>SCIENTIFIC SCALE</Badge></div>{data.length&&!reduced&&canRender?<WasteScene data={data}/>:<div className="waste-2d">{data.length?data.slice(0,5).map(d=><div key={d.name}><span>{d.name}</span><strong>{nf(d.value)} kg</strong></div>):<EmptyState title="No mass to visualize" description="Submit category-based measurements to activate this spatial scene."/>}</div>}</div>}
function TwinSection({mode,ws,data,reduced,onAdd}:{mode:Mode;ws:Workspace;data:Analytics;reduced:boolean;onAdd:()=>void}){
 const [selected,setSelected]=useState<string|null>(ws.zones[0]?.name||null),[noWebGL,setNoWebGL]=useState(false);
 useEffect(()=>{try{const canvas=document.createElement('canvas');setNoWebGL(!Boolean(canvas.getContext('webgl2')||canvas.getContext('webgl')))}catch{setNoWebGL(true)}},[]);
 const chosen=ws.zones.find(z=>z.name===selected)||ws.zones[0],zRows=data.rows.filter(r=>r.zone===chosen?.name);
 const waste=zRows.reduce((s,r)=>s+r.weight_kg,0),byCat=new Map<string,number>();zRows.forEach(r=>byCat.set(r.category,(byCat.get(r.category)||0)+r.weight_kg));
 const major=[...byCat.entries()].sort((a,b)=>b[1]-a[1]);const status=!zRows.length?'NO DATA':waste<chosen.threshold_low_kg?'LOW':waste<chosen.threshold_high_kg?'MODERATE':'HIGH';
 return <><div className="twin-topline"><div><span className="eyebrow"><span className="eyebrow-dot"/> INTERACTIVE CAMPUS MAP</span><h3>Your environmental digital twin</h3><p>Colors reflect recorded zone totals for the selected period, not live sensor activity.</p></div><div className="status-legend"><span><i className="green"/> Low</span><span><i className="yellow"/> Moderate</span><span><i className="red"/> High</span><span><i className="gray"/> No data</span></div></div>
 <div className="twin-layout"><div className="twin-viewport">{!ws.zones.length&&mode==='real'?<EmptyState title="No campus zones yet" description="Add named zones in Settings to map your real environmental observations." action={<Button size="small" onClick={onAdd}>Add a zone <Plus size={14}/></Button>}/>:reduced||noWebGL?<div className="fallback-twin"><p>2D accessible campus view</p><div>{ws.zones.map(z=><button key={z.id} className={selected===z.name?'selected':''} onClick={()=>setSelected(z.name)}>{z.name}</button>)}</div></div>:<CampusScene zones={ws.zones} byZone={data.by_zone} selected={selected} onSelect={setSelected}/>}<div className="twin-map-overlay"><div><span className="twin-label-dot"/> CAMPUS DIGITAL TWIN</div><span>MODE / {mode==='demo'?'SIMULATION':'RECORDED DATA'}</span></div></div><div className="twin-inspector"><span className="eyebrow"><span className="eyebrow-dot"/> ZONE INSPECTOR</span><h3>{chosen?.name||'Select a zone'}</h3><p>{mode==='demo'?'Simulated campus profile':'Recorded zone observations'}</p><Badge tone={status==='LOW'?'mint':status==='HIGH'?'rose':status==='MODERATE'?'amber':'muted'}>{status==='NO DATA'?'NO RECORDED AUDITS':`${status} WASTE`}</Badge><div className="inspector-stats"><div><small>MEASURED WASTE</small><strong>{zRows.length?nf(waste):'—'} <span>kg</span></strong></div><div><small>AUDITS</small><strong>{zRows.length}</strong></div><div><small>CONFIRMED RECYCLED</small><strong>{nf(zRows.reduce((s,r)=>s+r.confirmed_recycled_kg,0))} <span>kg</span></strong></div></div><h4>Top plastic sources</h4>{major.length?major.slice(0,3).map(([n,v],i)=><div className="inspector-category" key={n}><span>{n}</span><b>{nf(v)} kg</b></div>):<p className="muted-text">No category observations for this zone.</p>}<div className="inspector-reco"><Sparkles size={17}/><div><b>Evidence-based next step</b><p>{major.length?`Prioritize a targeted audit of ${major[0][0].toLowerCase()} and document one practical source-reduction action.`:'Start with a measured audit in this zone. Visual thresholds are configurable.'}</p></div></div><div className="threshold-note">Zone thresholds: Low &lt; {chosen?.threshold_low_kg??'—'} kg · High ≥ {chosen?.threshold_high_kg??'—'} kg <br/>Configured values are illustrative guidelines, not official standards.</div></div></div></>
}
function IntelligenceSection({mode,data,dates}:{mode:Mode;data:Analytics;dates:{start:string;end:string}}){
 const suggestions=['Which campus area generates the most plastic waste?','How much waste did we reduce compared with baseline?','What actions could reduce plastic consumption?','What is the confirmed recycling rate?'];
 const [question,setQuestion]=useState(''),[conversation,setConversation]=useState<{role:'user'|'assistant';text:string}[]>([{role:'assistant',text:'Hello! I am your EcoSphere intelligence guide. I use recorded measurements or clearly labeled demonstration observations. Ask me to investigate a trend, compare periods, or suggest a reduction action.'}]),[busy,setBusy]=useState(false);
 function demoReply(q:string){const m=data.metrics;const zone=data.by_zone[0],cat=data.by_category[0];if(!m.audits)return 'There are no recorded observations in the selected period.';if(/where|zone|area|highest/.test(q.toLowerCase()))return zone?`${zone.name} has the highest SIMULATED waste total (${nf(zone.value)} kg). This is demo data, not a campus finding.`:'No zone observations are available.';if(/recycl/.test(q.toLowerCase()))return `In this simulated period, ${nf(m.recycled_kg)} kg is marked confirmed recycled out of ${nf(m.total_kg)} kg (${nf(m.recycling_rate)}%). These are demo figures.`;if(/reduc|baseline|compar/.test(q.toLowerCase()))return m.reduction_kg!==null?`Simulated waste ${m.reduction_kg>=0?'decreased':'increased'} by ${nf(Math.abs(m.reduction_kg))} kg versus a matched prior period. This is NOT actual environmental impact.`:'No matched baseline observations are available.';return `Rule-based suggestion for SIMULATED observations: target ${cat?.name.toLowerCase()||'the highest category'}, establish reuse/refill options, repeat the same weighing protocol after 7 days, and retain independent evidence. No improvement has been verified.`}
 async function send(q=question){if(!q.trim()||busy)return;setQuestion('');setConversation(v=>[...v,{role:'user',text:q}]);setBusy(true);try{const text=mode==='demo'?demoReply(q):(await api<{answer:string}>('/api/assistant',{method:'POST',body:JSON.stringify({question:q,start:dates.start,end:dates.end})})).answer;setConversation(v=>[...v,{role:'assistant',text}])}catch(e){setConversation(v=>[...v,{role:'assistant',text:e instanceof Error?e.message:'Assistant unavailable'}])}finally{setBusy(false)}}
 return <div className="intelligence-layout"><div className="assistant-panel"><div className="assistant-header"><div className="assistant-avatar"><BrainCircuit size={23}/></div><div><b>EcoSphere Intelligence</b><span><i/> DETERMINISTIC ANALYTICS ENGINE · NO UNVERIFIED MEASUREMENTS</span></div><Badge>RULE-BASED AI</Badge></div><div className="assistant-messages" aria-live="polite">{conversation.map((line,i)=><div key={i} className={`chat-bubble ${line.role==='user'?'user-bubble':'ai-bubble'}`}><span>{line.role==='user'?'YOU':'✧ ECOSPHERE'}</span><p>{line.text}</p></div>)}{busy&&<div className="ai-typing">Analyzing recorded observations <span className="typing-dots">•••</span></div>}</div><form onSubmit={e=>{e.preventDefault();void send()}} className="assistant-input"><input aria-label="Ask EcoSphere AI" value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Ask about plastic, waste trends, or reduction actions..." maxLength={600}/><button disabled={busy||!question.trim()} aria-label="Send question"><ArrowUpRight size={20}/></button></form></div><div className="intelligence-side"><span className="eyebrow"><span className="eyebrow-dot"/> SUGGESTED QUERIES</span><h3>Ask better questions.</h3><p>Environmental intelligence starts with precise measurements and clear questions.</p><div className="suggestion-list">{suggestions.map(q=><button key={q} onClick={()=>void send(q)}>{q}<ArrowUpRight size={17}/></button>)}</div><div className="ai-guardrail"><ShieldCheck size={20}/><p>Answers use recorded audit values. Model forecasting is exploratory and never treated as measured impact. External LLM credentials are not required.</p></div></div></div>
}
function RecyclingSection({mode,data,role,onUpdated}:{mode:Mode;data:Analytics;role?:string;onUpdated:()=>Promise<void>}){
 const [itemId,setItemId]=useState(''),[weight,setWeight]=useState(''),[status,setStatus]=useState(''),[busy,setBusy]=useState(false);const eligible=data.rows.filter(r=>r.recyclable&&r.weight_kg-r.confirmed_recycled_kg>0);
 async function submit(){setBusy(true);setStatus('');try{await api('/api/recycling',{method:'POST',body:JSON.stringify({audit_item_id:itemId,confirmed_weight_kg:Number(weight)})});setStatus('Recycled weight confirmed. Only verified processing outcomes should be entered.');setWeight('');await onUpdated()}catch(e){setStatus(e instanceof Error?e.message:'Confirmation failed')}finally{setBusy(false)}}
 return <><div className="recycling-stats"><KpiCard icon={Recycle} label="Confirmed Recycled" value={nf(data.metrics.recycled_kg)} unit="kg" detail="Outcomes marked confirmed"/><KpiCard icon={Activity} label="Measured Total" value={nf(data.metrics.total_kg)} unit="kg" detail="Weight counted for rate"/><KpiCard icon={ShieldCheck} label="Recycling Rate" value={nf(data.metrics.recycling_rate)} unit="%" detail="Recycled / total × 100"/></div><div className="two-col"><RecyclingChart rows={data.rows}/><div className="glass-panel recycler-form"><span className="eyebrow"><span className="eyebrow-dot"/> OUTCOME VERIFICATION</span><h3>Confirm recycling</h3><p>Only authorized admins/reviewers may confirm actual recycled weights. Recyclability or sending waste to a collection point is not proof of recycling.</p>{mode==='real'&&['admin','reviewer'].includes(role||'')?<form onSubmit={e=>{e.preventDefault();void submit()}}><label>Audited plastic item<select required value={itemId} onChange={e=>setItemId(e.target.value)}><option value="">Choose recorded item</option>{eligible.map(r=><option key={r.item_id} value={r.item_id}>{r.submission_id} · {r.item_type} · {nf(r.weight_kg-r.confirmed_recycled_kg)} kg remaining</option>)}</select></label><label>Confirmed recycled weight (kg)<input type="number" min="0.0001" step="0.0001" value={weight} required onChange={e=>setWeight(e.target.value)}/></label><Button disabled={busy||!itemId||!Number(weight)} type="submit">Confirm weight <Check size={16}/></Button></form>:<div className="note-inline">{mode==='demo'?'Read-only in Demo Mode. Switch to a real campus to record confirmed outcomes.':'Reviewer or administrator permissions required.'}</div>}{status&&<p role="status" className="form-note">{status}</p>}</div></div></>
}
type Action={id:string;title:string;description:string;status:string;implemented_on:string|null;zone_id:string|null};
type Goal={id:string;name:string;target_kg:number;target_date:string;created_at:string};
type ImpactEntry={id:string;label:string;measured_on:string;weight_kg:number;measurement_notes:string};
type ImpactResponse={entries:ImpactEntry[];comparison:{before_kg:number|null;after_kg:number|null;reduction_kg:number|null;caution:string}};
function BeforeAfterSlider({before,after}:{before:Evidence|undefined;after:Evidence|undefined}){
 const [position,setPosition]=useState(50),[urls,setUrls]=useState<{before?:string;after?:string}>({});
 useEffect(()=>{let done=false;const created:string[]=[];async function load(){try{const next:{before?:string;after?:string}={};if(before){next.before=await evidenceBlob(before.download_url);created.push(next.before)}if(after){next.after=await evidenceBlob(after.download_url);created.push(next.after)}if(!done)setUrls(next)}catch{if(!done)setUrls({})}}void load();return()=>{done=true;created.forEach(URL.revokeObjectURL)}},[before?.id,after?.id]);
 if(!before||!after)return <div className="slider-empty">Upload a BEFORE and AFTER photograph to the selected intervention for a visual comparison. Photos remain unverified until reviewed.</div>;
 if(!urls.before||!urls.after)return <Skeleton height={205}/>;
 return <div className="comparison-slider"><div className="slider-image slider-after" style={{backgroundImage:`url('${urls.after}')`}}/><div className="slider-image slider-before" style={{backgroundImage:`url('${urls.before}')`,clipPath:`inset(0 ${100-position}% 0 0)`}}/><div className="slider-handle" style={{left:`${position}%`}}><span>↔</span></div><div className="slider-labels"><b>BEFORE</b><b>AFTER</b></div><input aria-label="Compare before and after photographs" type="range" min={0} max={100} value={position} onChange={e=>setPosition(Number(e.target.value))}/></div>;
}
function GoalsSection({mode,data,onUpdate,ws}:{mode:Mode;data:Analytics;onUpdate:()=>Promise<void>;ws:Workspace}){
 const [goals,setGoals]=useState<Goal[]>([]),[goalName,setGoalName]=useState(''),[goalMass,setGoalMass]=useState(''),[goalDate,setGoalDate]=useState(initialDates().end);
 const [actions,setActions]=useState<Action[]>([]),[selected,setSelected]=useState(''),[title,setTitle]=useState(''),[desc,setDesc]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const [impact,setImpact]=useState<ImpactResponse|null>(null),[evidence,setEvidence]=useState<Evidence[]>([]),[stage,setStage]=useState<'before'|'after'>('before'),[weight,setWeight]=useState(''),[when,setWhen]=useState(initialDates().end),[note,setNote]=useState(''),[image,setImage]=useState<File|null>(null),[uploading,setUploading]=useState(false);
 const refreshActions=useCallback(async()=>{if(mode!=='real')return;const [next, targets]=await Promise.all([api<Action[]>('/api/actions'),api<Goal[]>('/api/goals')]);setActions(next);setGoals(targets);setSelected(v=>v||next[0]?.id||'')},[mode]);
 useEffect(()=>{if(mode==='real')void refreshActions().catch(e=>setError(String(e)));else{setActions([]);setGoals([]);setSelected('')}},[mode,refreshActions]);
 const refreshImpact=useCallback(async()=>{if(mode!=='real'||!selected){setImpact(null);setEvidence([]);return}const [result,files]=await Promise.all([api<ImpactResponse>(`/api/actions/${selected}/measurements`),api<Evidence[]>('/api/evidence')]);setImpact(result);setEvidence(files.filter(e=>e.action_id===selected))},[mode,selected]);
 useEffect(()=>{void refreshImpact().catch(e=>setError(e instanceof Error?e.message:String(e)))},[refreshImpact]);
 async function add(){setBusy(true);setError('');try{const action=await api<Action>('/api/actions',{method:'POST',body:JSON.stringify({title,description:desc,status:'planned'})});setTitle('');setDesc('');setSelected(action.id);await refreshActions()}catch(e){setError(e instanceof Error?e.message:'Could not add action')}finally{setBusy(false)}}
 async function addGoal(){setBusy(true);setError('');try{await api<Goal>('/api/goals',{method:'POST',body:JSON.stringify({name:goalName,target_kg:Number(goalMass),target_date:goalDate})});setGoalName('');setGoalMass('');await refreshActions()}catch(e){setError(e instanceof Error?e.message:'Could not create sustainability goal')}finally{setBusy(false)}}
 async function addMeasurement(){if(!selected)return;setBusy(true);setError('');try{await api(`/api/actions/${selected}/measurements`,{method:'POST',body:JSON.stringify({label:stage,measured_on:when,weight_kg:Number(weight),measurement_notes:note})});setWeight('');setNote('');await refreshImpact();await onUpdate()}catch(e){setError(e instanceof Error?e.message:'Could not record measurement')}finally{setBusy(false)}}
 async function uploadPhoto(){if(!selected||!image)return;setUploading(true);setError('');try{const fd=new FormData();fd.set('file',image);await api(`/api/evidence?action_id=${encodeURIComponent(selected)}&stage=${stage}`,{method:'POST',body:fd});setImage(null);await refreshImpact()}catch(e){setError(e instanceof Error?e.message:'Upload failed')}finally{setUploading(false)}}
 const beforePhoto=evidence.find(e=>e.stage==='before'&&e.content_type.startsWith('image/')),afterPhoto=evidence.find(e=>e.stage==='after'&&e.content_type.startsWith('image/'));
 return <><section className="glass-panel goal-target-panel"><div className="goal-target-heading"><div><span className="eyebrow"><span className="eyebrow-dot"/> MEASURABLE GOALS</span><h3>Sustainability targets, grounded in data.</h3><p>Choose an absolute plastic reduction target in kilograms. Progress uses the prior matched period and current records; it is provisional until collection methods are checked.</p></div><Target size={34} color="#81eab2"/></div><div className="goal-target-grid">{goals.map(g=>{const valid=data.metrics.reduction_kg!==null;const observed=Math.max(0,data.metrics.reduction_kg||0);const percent=Math.max(0,Math.min(100,(observed/g.target_kg)*100));return <div className="goal-target-item" key={g.id}><div className="goal-target-label"><strong>{g.name}</strong><span>{g.target_date}</span></div><div className="goal-progress"><i style={{width:`${valid?percent:0}%`}}/></div><div className="goal-progress-details"><span>{valid?`${nf(observed)} kg observed reduction`:'Baseline required'}</span><b>Target {nf(g.target_kg)} kg</b></div></div>})}{!goals.length&&<p className="muted-text">{mode==='demo'?'Goals are not fabricated in public demo mode.':'No configured goals yet. Create your first measurable reduction target below.'}</p>}</div>{mode==='real'&&<form className="goal-target-form" onSubmit={e=>{e.preventDefault();void addGoal()}}><label>Goal name<input required minLength={3} maxLength={180} value={goalName} onChange={e=>setGoalName(e.target.value)} placeholder="e.g. Reduce cafeteria plastic waste"/></label><label>Reduction target (kg)<input required type="number" min="0.0001" step="0.0001" value={goalMass} onChange={e=>setGoalMass(e.target.value)} placeholder="2.50"/></label><label>Target date<input required type="date" min={initialDates().end} value={goalDate} onChange={e=>setGoalDate(e.target.value)}/></label><Button size="small" disabled={busy||!goalName.trim()||!(Number(goalMass)>0)} type="submit"><Plus size={15}/> Set target</Button></form>}<p className="tiny-note">Goal progress is a comparison of observed audit masses, not independently verified environmental impact.</p></section><div className="two-col"><div className="glass-panel goal-panel"><span className="eyebrow"><span className="eyebrow-dot"/> IMPACT TRACKING</span><h3>Before → Action → After → Impact</h3><p>Actual reductions require comparable baseline and follow-up measurements. Record an intervention, then repeat the observation protocol.</p><div className="impact-steps">{['01 BASELINE','02 ACTION','03 FOLLOW-UP','04 IMPACT'].map((a,i)=><div key={a}><span>{a}</span><div className={i===0&&data.baseline.available?'done':''}>{i===0&&data.baseline.available?'✓':'—'}</div></div>)}</div><div className="goal-metric"><span>Comparable period change</span><strong>{data.metrics.reduction_kg===null?'No baseline':`${nf(data.metrics.reduction_kg)} kg`}</strong><small>Negative = increase. Differences in audit intensity can distort this comparison.</small></div><div className="action-list"><h4>Recorded interventions</h4>{actions.length?actions.map(a=><button className={`action-select ${selected===a.id?'active':''}`} key={a.id} onClick={()=>setSelected(a.id)}><Badge tone="amber">{a.status.replace('_',' ')}</Badge><b>{a.title}</b><small>{a.description||'No implementation notes'}</small></button>):<p className="muted-text">No real interventions have been recorded.</p>}</div></div><div className="glass-panel goal-panel"><span className="eyebrow"><span className="eyebrow-dot"/> CORRECTIVE ACTIONS</span><h3>Improvement action plan</h3><p>Track your intervention independently from its measured results.</p>{mode==='real'?<form onSubmit={e=>{e.preventDefault();void add()}}><label>Action title<input required minLength={3} maxLength={180} value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Install refill stations"/></label><label>Implementation details<textarea value={desc} maxLength={3000} rows={3} onChange={e=>setDesc(e.target.value)} placeholder="Responsible team, location, follow-up plan..."/></label><Button disabled={busy||!title.trim()} type="submit"><Plus size={15}/> Add action</Button></form>:<div className="note-inline">Simulated preview only. Create real actions in Real Audit Mode.</div>}{error&&<p className="form-error">{error}</p>}</div></div>{mode==='real'&&selected&&<div className="impact-detail"><div className="glass-panel"><span className="eyebrow"><span className="eyebrow-dot"/> WEIGHED OBSERVATIONS</span><h3>Log before and after measurements</h3><div className="form-grid"><label>Measurement stage<select value={stage} onChange={e=>setStage(e.target.value as 'before'|'after')}><option value="before">Before</option><option value="after">After</option></select></label><label>Date<input type="date" max={initialDates().end} value={when} onChange={e=>setWhen(e.target.value)}/></label><label>Measured waste (kg)<input type="number" min={0} step="0.0001" value={weight} onChange={e=>setWeight(e.target.value)}/></label><label>Conditions / method<input value={note} onChange={e=>setNote(e.target.value)} placeholder="e.g. 7-day collection, same scale"/></label></div><Button size="small" disabled={busy||weight===''} onClick={()=>void addMeasurement()}>Save measurement <Check size={15}/></Button><div className="measurement-list">{impact?.entries.map(e=><div key={e.id}><Badge tone={e.label==='before'?'amber':'mint'}>{e.label.toUpperCase()}</Badge><span>{e.measured_on}</span><b>{nf(e.weight_kg)} kg</b></div>)}</div><div className="goal-metric"><span>Before − After</span><strong>{impact?.comparison.reduction_kg===null||impact?.comparison.reduction_kg===undefined?'Awaiting paired measurements':`${nf(impact.comparison.reduction_kg)} kg`}</strong><small>Informational only until periods, sampling effort and reviewer evidence are comparable.</small></div></div><div className="glass-panel"><span className="eyebrow"><span className="eyebrow-dot"/> PHOTO DOCUMENTATION</span><h3>Before / After Visual Record</h3><BeforeAfterSlider before={beforePhoto} after={afterPhoto}/><div className="upload-impact"><label>Photograph stage <select value={stage} onChange={e=>setStage(e.target.value as 'before'|'after')}><option value="before">Before</option><option value="after">After</option></select></label><label>Photo <input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setImage(e.target.files?.[0]||null)}/></label><Button size="small" variant="outline" disabled={uploading||!image} onClick={()=>void uploadPhoto()}><Upload size={15}/>{uploading?'Uploading…':'Upload evidence'}</Button></div><p className="tiny-note">Images remain private and PENDING until an authorized reviewer approves them. A comparison does not independently prove waste reduction.</p></div></div>}</>
}

function ReportsSection({mode,data,dates,onExport}:{mode:Mode;data:Analytics;dates:{start:string;end:string};onExport:(type:'pdf'|'csv')=>Promise<void>}){
 return <div className="report-layout"><div className="report-preview"><div className="report-cover"><span className="report-cover-badge"><Leaf size={18}/> ECOSPHERE AI</span><div><small>ENVIRONMENTAL AUDIT REPORT</small><h2>Building a Plastic-Free Tomorrow.</h2><p>Responsible consumption starts with responsible measurement.</p></div><div className="report-cover-bottom"><span>REPORTING PERIOD<br/><b>{dates.start} — {dates.end}</b></span><span>DEVELOPED BY<br/><b>RAJA · 2026</b></span></div></div></div><div className="report-options"><span className="eyebrow"><span className="eyebrow-dot"/> PROFESSIONAL REPORTING</span><h3>Turn observations into a credible story.</h3><p>Generate a PDF audit summary with methodology, baseline, measurements, category tables, limitations, and recommendations. The developer attribution is included in every report.</p><div className="report-metadata"><div><small>AUDITS IN PERIOD</small><b>{data.metrics.audits}</b></div><div><small>MEASURED WEIGHT</small><b>{nf(data.metrics.total_kg)} kg</b></div><div><small>BASELINE</small><b>{data.baseline.available?'Recorded':'Not available'}</b></div></div>{mode==='demo'?<p className="note-inline">This is SIMULATED DATA. For evidence-based PDF and CSV reports, switch to Real Audit Mode and enter observations.</p>:<div className="report-buttons"><Button onClick={()=>void onExport('pdf')}><Download size={16}/> Download PDF</Button><Button variant="outline" onClick={()=>void onExport('csv')}><Download size={16}/> Export CSV</Button><Button variant="outline" onClick={()=>window.print()}><FileText size={16}/> Print Page</Button></div>}<div className="report-explain"><ShieldCheck size={18}/> Confirmed recycling only · Zero-baseline cases explicitly stated · No unsupported carbon claims.</div></div></div>
}
function EvidenceSection({mode,items,role,onUpdate}:{mode:Mode;items:Evidence[];role?:string;onUpdate:()=>Promise<void>}){
 const [status,setStatus]=useState(''),[previews,setPreviews]=useState<Record<string,string>>({}),[loading,setLoading]=useState('');
 const urls=useRef<string[]>([]);
 async function show(e:Evidence){setLoading(e.id);try{const url=await evidenceBlob(e.download_url);urls.current.push(url);setPreviews(v=>({...v,[e.id]:url}));}catch(err){setStatus(err instanceof Error?err.message:'Unable to preview evidence')}finally{setLoading('')}}
 useEffect(()=>()=>{urls.current.forEach(url=>URL.revokeObjectURL(url));urls.current=[]},[]);
 async function verify(id:string,v:'approved'|'rejected'|'reviewed'){try{await api(`/api/evidence/${id}/review`,{method:'POST',body:JSON.stringify({status:v,notes:'Reviewed in EcoSphere evidence gallery'})});setStatus(`Evidence marked ${v}.`);await onUpdate()}catch(e){setStatus(e instanceof Error?e.message:'Review failed')}}
 return <div className="evidence-wrapper"><div className="section-intro"><div><h3>Environmental evidence library</h3><p>Uploaded files are private, access-controlled, and pending review until authorized staff verify them.</p></div><div className="evidence-count"><Camera size={16}/>{mode==='demo'?'0 ACTUAL FILES':`${items.length} FILES`}</div></div>{mode==='demo'?<EmptyState title="Evidence is not simulated" description="Real photos and recycling receipts are never fabricated. Switch to Real Audit Mode to attach evidence to a submitted audit."/>:items.length?<div className="evidence-grid">{items.map(e=><div className="evidence-card" key={e.id}><div className="evidence-preview">{previews[e.id]?(e.content_type.startsWith('image/')?<img src={previews[e.id]} alt={`Evidence file ${e.file_name}`}/>:<a target="_blank" rel="noopener noreferrer" href={previews[e.id]}>Open PDF</a>):<button onClick={()=>void show(e)}>{loading===e.id?'Loading…':<><Camera size={26}/>Preview evidence</>}</button>}</div><div className="evidence-meta"><b title={e.file_name}>{e.file_name}</b><small>{new Date(e.created_at).toLocaleDateString()} · {(e.size_bytes/1024).toFixed(0)} KB</small><Badge tone={e.status==='approved'?'mint':e.status==='rejected'?'rose':'amber'}>{e.status.toUpperCase()}</Badge>{['admin','reviewer'].includes(role||'')&&<div className="review-actions"><button onClick={()=>void verify(e.id,'approved')}>Approve</button><button onClick={()=>void verify(e.id,'rejected')}>Reject</button></div>}</div></div>)}</div>:<EmptyState title="Your evidence library is empty" description="Attach before/after photos, weighing records, and receipts when creating or editing an audit."/>}{status&&<p role="status" className="form-note">{status}</p>}</div>
}
function LeaderboardSection({data,rows,dates}:{data:Analytics;rows:Audit[];dates:{start:string;end:string}}){const candidates=data.by_department.map(d=>({...d}));return <><div className="leaderboard-hero"><div><span className="eyebrow"><span className="eyebrow-dot"/> POSITIVE COMPETITION</span><h3>Impact earns recognition.</h3><p>Rankings require verifiable reduction, recycling performance, and completed actions — not simply more submissions.</p></div><Trophy size={72} strokeWidth={1}/></div><EmptyState title="Verified rankings are not available yet" description="To publish a fair department leaderboard, each department needs a comparable baseline, confirmed recycling, reviewer-approved evidence, and recorded actions. Raw audit totals alone do not earn points."/><div className="records-section"><h3>Audit participation by department</h3><p className="subheading-text">Unranked activity only · {data.period.start} to {data.period.end}</p><div className="category-list">{data.by_department.map((d,i)=><div key={d.name}><span className="list-number">{String(i+1).padStart(2,'0')}</span><b>{d.name}</b><div className="category-bar"><i style={{width:`${d.value/(data.by_department[0]?.value||1)*100}%`}}/></div><span>{nf(d.value)} kg measured</span></div>)}{!data.by_department.length&&<p className="muted-text">No departmental activity in this period.</p>}</div></div></>}
function SettingsSection({mode,me,workspace,onRefresh,onLogout}:{mode:Mode;me:Me|null;workspace:Workspace;onRefresh:()=>Promise<void>;onLogout:()=>Promise<void>}){const [weights,setWeights]=useState<Record<string,number>>({reduction:30,recycling:25,single_use_reduction:15,audit_completion:15,evidence_quality:15}),[auditTarget,setAuditTarget]=useState(5),[kind,setKind]=useState<'departments'|'zones'|'categories'>('zones'),[name,setName]=useState(''),[low,setLow]=useState('5'),[high,setHigh]=useState('20'),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{if(workspace.scoring){setWeights(workspace.scoring.score_weights);setAuditTarget(workspace.scoring.audit_target_weekly)}},[workspace.scoring]);
 async function saveScoring(){setBusy(true);setMessage('');try{await api('/api/scoring',{method:'PUT',body:JSON.stringify({audit_target_weekly:auditTarget,score_weights:weights})});setMessage('Scoring model saved and recalculated.');await onRefresh()}catch(e){setMessage(e instanceof Error?e.message:'Could not save scoring configuration')}finally{setBusy(false)}}
 async function add(){setBusy(true);setMessage('');try{const body={name,...(kind==='zones'?{kind:'building',threshold_low_kg:Number(low),threshold_high_kg:Number(high)}:{})};await api(`/api/${kind}`,{method:'POST',body:JSON.stringify(body)});setName('');setMessage('Workspace updated.');await onRefresh()}catch(e){setMessage(e instanceof Error?e.message:'Could not update settings')}finally{setBusy(false)}}return <div className="settings-grid"><div className="glass-panel settings-panel"><span className="eyebrow"><span className="eyebrow-dot"/> WORKSPACE CONFIGURATION</span><h3>Campus configuration</h3><p>Measurement thresholds are configurable in kilograms for the selected reporting period.</p><div className="settings-stat"><span>Workspace</span><b>{mode==='demo'?'Simulated Evergreen Campus':me?.campus?.name||'Not configured'}</b></div><div className="settings-stat"><span>Permissions</span><Badge>{mode==='demo'?'Read-only demo':me?.role||'Visitor'}</Badge></div><div className="settings-stat"><span>Zones</span><b>{workspace.zones.length}</b></div><div className="settings-stat"><span>Departments</span><b>{workspace.departments.length}</b></div><div className="settings-stat"><span>Waste categories</span><b>{workspace.categories.length}</b></div>{mode==='real'&&!devMode&&<Button variant="outline" size="small" onClick={()=>void onLogout()}><LogOut size={16}/> Sign out</Button>}</div><div className="glass-panel settings-panel"><span className="eyebrow"><span className="eyebrow-dot"/> ADMINISTRATOR ACTION</span><h3>Add campus resources</h3><p>Admins can create categories, buildings/zones, and departments without changing historical measurements.</p><form onSubmit={e=>{e.preventDefault();void add()}}><label>Resource type<select value={kind} onChange={e=>setKind(e.target.value as typeof kind)}><option value="zones">Campus Zone</option><option value="departments">Department</option><option value="categories">Plastic Category</option></select></label><label>Name<input value={name} minLength={2} required maxLength={120} onChange={e=>setName(e.target.value)} placeholder="Enter resource name"/></label>{kind==='zones'&&<div className="form-grid"><label>Low threshold (kg)<input type="number" min="0" step="0.1" required value={low} onChange={e=>setLow(e.target.value)}/></label><label>High threshold (kg)<input type="number" min="0.1" step="0.1" required value={high} onChange={e=>setHigh(e.target.value)}/></label></div>}<Button disabled={busy||mode==='demo'||me?.role!=='admin'||!name.trim()} type="submit"><Plus size={15}/> Add resource</Button></form>{message&&<p className="form-note">{message}</p>}{mode==='demo'&&<div className="note-inline">Changes are disabled for demo mode.</div>}<div className="existing-zones"><h4>Current zones</h4>{workspace.zones.map(z=><div key={z.id}><span>{z.name}</span><small>{z.threshold_low_kg} / {z.threshold_high_kg} kg</small></div>)}</div></div><div className="glass-panel scoring-panel"><span className="eyebrow"><span className="eyebrow-dot"/> TRANSPARENT IMPACT SCORING</span><h3>Configure your sustainability index</h3><p>The provisional EcoSphere score uses five disclosed percentage weights and a weekly audit target. Weights must sum to 100%.</p><div className="scoring-fields">{Object.entries(weights).map(([k,v])=><label key={k}>{k.replaceAll('_',' ')} <input type="number" min={0} max={100} step={1} value={v} onChange={e=>setWeights(x=>({...x,[k]:Number(e.target.value)}))}/><span>%</span></label>)}<label>Weekly audit target <input type="number" min={1} max={365} value={auditTarget} onChange={e=>setAuditTarget(Number(e.target.value))}/><span>audits</span></label></div><p>Total allocated: <strong className={Object.values(weights).reduce((a,b)=>a+b,0)===100?'good-score':'bad-score'}>{Object.values(weights).reduce((a,b)=>a+b,0)}%</strong></p><Button size="small" disabled={mode==='demo'||me?.role!=='admin'||busy||Object.values(weights).reduce((a,b)=>a+b,0)!==100} onClick={()=>void saveScoring()}><Check size={15}/> Save scoring model</Button></div></div>}
